entries[95467] = { ["name"] = "Muster: Pracht des Leders", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Lederverarbeitung (500)\nBenutzen: Lehrt Euch 'Pracht des Leders'.\nStellt einmal pro Tag einen prächtigen Balg aus nebelberührtem Leder her. Dabei könnt Ihr Euer Wissen über pandarische Lederverarbeitung vergrößern und ein neues Schnittmuster erlernen. Teilt eine Abklingzeit mit 'Pracht der Schuppen'.\n\nPrächtiger Balg\nVerkaufspreis:\nBenötigt Nebelberührtes Leder (20)" }
entries[95468] = { ["name"] = "Muster: Pracht der Schuppen", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Lederverarbeitung (500)\nBenutzen: Lehrt Euch 'Pracht der Schuppen'.\nStellt einmal pro Tag einen prächtigen Balg aus prismatischen Schuppen her. Dabei könnt Ihr Euer Wissen über pandarische Lederverarbeitung vergrößern und ein neues Schnittmuster erlernen. Teilt eine Abklingzeit mit 'Pracht des Leders'.\n\nPrächtiger Balg\nVerkaufspreis:\nBenötigt Prismatische Schuppe (20)" }
